import test from 'node:test';
import assert from 'node:assert/strict';
import {withD1Fault,RESERVE_SQL,SETTLE_SQL} from '../dev/d1-readiness/fault-binding.mjs';
function fake(){const log=[];return {log,prepare(sql){return {sql,bind(...args){log.push(['bind',sql,args]);return {...this,args};},all(){return this.sql;}};},async batch(batch){log.push(['commit',batch]);if(this.fail)throw this.fail;return batch.map(()=>({success:true,results:[]}));}};}
const batch=(db,settle=false)=>[db.prepare(settle?SETTLE_SQL:RESERVE_SQL).bind(1),db.prepare(settle?'SELECT state,charge_micros,result_json,error_code FROM tutor_claims WHERE token=?':'SELECT * FROM tutor_claims WHERE claim_key=?').bind(2)];
test('default disabled transparently passes statements/results and methods',async()=>{const db=fake(),wrapped=withD1Fault(db);assert.equal(wrapped.prepare('hello').all(),'hello');const result=await wrapped.batch(batch(wrapped));assert.deepEqual(result,[{success:true,results:[]},{success:true,results:[]}]);assert.equal(db.log.filter(x=>x[0]==='commit').length,1);assert.equal(db.log.at(-1)[1][0].sql,RESERVE_SQL);});
test('reservation and settlement lost acknowledgments occur only after real batch success, once',async()=>{for(const point of ['reservation-after','settlement-after']){const db=fake(),w=withD1Fault(db,point),b=batch(w,point.startsWith('settlement'));await assert.rejects(w.batch(b),/LOST_ACK/);assert.equal(db.log.filter(x=>x[0]==='commit').length,1);await w.batch(b);assert.equal(db.log.filter(x=>x[0]==='commit').length,2);}});
test('settlement before failure never invokes first batch, next invocation passes',async()=>{const db=fake(),w=withD1Fault(db,'settlement-before'),b=batch(w,true);await assert.rejects(w.batch(b),/BEFORE_COMMIT/);assert.equal(db.log.filter(x=>x[0]==='commit').length,0);await w.batch(b);assert.equal(db.log.filter(x=>x[0]==='commit').length,1);});
test('exact SQL, order and count required; non-target batch does not consume fault',async()=>{const db=fake(),w=withD1Fault(db,'reservation-after'),b=batch(w);for(const nonTarget of [[b[0]],b.slice().reverse(),[...b,b[1]],[w.prepare(RESERVE_SQL+' '),b[1]],batch(w,true)])await w.batch(nonTarget);await assert.rejects(w.batch(b),/LOST_ACK/);assert.equal(db.log.filter(x=>x[0]==='commit').length,6);});
test('native database failure is not swallowed or replaced and consumes matched once point',async()=>{const db=fake(),w=withD1Fault(db,'reservation-after'),b=batch(w),failure=Error('native rollback');db.fail=failure;await assert.rejects(w.batch(b),e=>e===failure);db.fail=null;await w.batch(b);assert.equal(db.log.filter(x=>x[0]==='commit').length,2);});
test('invalid or inherited fault configuration fails closed',()=>{for(const point of ['constructor','__proto__','random',null])assert.throws(()=>withD1Fault(fake(),point),/Invalid development fault/);});
test('concurrent matching calls consume fault before awaiting, exactly one loses acknowledgment',async()=>{const db=fake();let release;const gate=new Promise(r=>release=r),native=db.batch;db.batch=async function(b){await gate;return native.call(this,b);};const w=withD1Fault(db,'reservation-after'),b=batch(w),one=w.batch(b),two=w.batch(b);release();const results=await Promise.allSettled([one,two]);assert.equal(results[0].status,'rejected');assert.match(results[0].reason.message,/LOST_ACK/);assert.equal(results[1].status,'fulfilled');assert.equal(db.log.filter(x=>x[0]==='commit').length,2);});
test('non-target native exception leaves target fault armed',async()=>{const db=fake(),w=withD1Fault(db,'settlement-after');db.fail=Error('native other batch');await assert.rejects(w.batch(batch(w)),/native other batch/);db.fail=null;await assert.rejects(w.batch(batch(w,true)),/LOST_ACK/);});
